import { sql } from 'drizzle-orm'
import {
	boolean,
	index,
	pgTable,
	text,
	timestamp,
	uuid,
} from 'drizzle-orm/pg-core'

// Better Auth's core schema, generated once with `bunx --bun auth@1.7.12 generate` and then revised:
// uuid ids generated by Postgres (architecture.md D28), timestamptz, and the `locale` additional field (D35).

const id = () => uuid().primaryKey().default(sql`uuidv7()`)
const timestamps = {
	createdAt: timestamp({ withTimezone: true }).notNull(),
	updatedAt: timestamp({ withTimezone: true })
		.notNull()
		.$onUpdate(() => new Date()),
}

export const user = pgTable('user', {
	id: id(),
	name: text().notNull(),
	email: text().notNull().unique(),
	emailVerified: boolean().notNull().default(false),
	image: text(),
	locale: text().notNull().default('en-US'),
	...timestamps,
})

export const session = pgTable(
	'session',
	{
		id: id(),
		expiresAt: timestamp({ withTimezone: true }).notNull(),
		token: text().notNull().unique(),
		ipAddress: text(),
		userAgent: text(),
		userId: uuid()
			.notNull()
			.references(() => user.id, { onDelete: 'cascade' }),
		...timestamps,
	},
	(table) => [index('session_user_id_idx').on(table.userId)],
)

export const account = pgTable(
	'account',
	{
		id: id(),
		accountId: text().notNull(),
		providerId: text().notNull(),
		userId: uuid()
			.notNull()
			.references(() => user.id, { onDelete: 'cascade' }),
		accessToken: text(),
		refreshToken: text(),
		idToken: text(),
		accessTokenExpiresAt: timestamp({ withTimezone: true }),
		refreshTokenExpiresAt: timestamp({ withTimezone: true }),
		scope: text(),
		password: text(),
		...timestamps,
	},
	(table) => [index('account_user_id_idx').on(table.userId)],
)

export const verification = pgTable(
	'verification',
	{
		id: id(),
		identifier: text().notNull(),
		value: text().notNull(),
		expiresAt: timestamp({ withTimezone: true }).notNull(),
		...timestamps,
	},
	(table) => [index('verification_identifier_idx').on(table.identifier)],
)
